const fs = require('fs');
const DECISOES = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\decisoes.md';
const ALERTAS = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\alertas-automaticos.md';
const ESTADO = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\automacao-n8n\\estado-decisoes.json';

const content = fs.readFileSync(DECISOES, 'utf8');
const lines = content.split(/\r?\n/);

const linhas = [];
for (const line of lines) {
  const t = line.trim();
  if (!t.startsWith('|')) continue;
  const cells = t.split('|').slice(1, -1).map(c => c.trim());
  if (cells.length !== 9) continue;
  const [data, categoria] = cells;
  if (data === 'data' || data === '---') continue;
  linhas.push({ data, categoria, resumo: cells[3].replace(/\*\*/g,'').slice(0, 110) });
}

let estadoAnterior = { total: 0 };
try { estadoAnterior = JSON.parse(fs.readFileSync(ESTADO, 'utf8')); } catch (e) {}

const novasLinhas = linhas.slice(estadoAnterior.total || 0);

fs.writeFileSync(ESTADO, JSON.stringify({ total: linhas.length, atualizadoEm: new Date().toISOString() }, null, 2), 'utf8');

const agora = new Date();
const pad = n => String(n).padStart(2, '0');
const dataStr = `${agora.getUTCFullYear()}-${pad(agora.getUTCMonth()+1)}-${pad(agora.getUTCDate())}`;
const horaStr = `${pad(agora.getUTCHours())}:${pad(agora.getUTCMinutes())}`;

let bloco = `\n## ${dataStr} ${horaStr} — n8n (automático, Guardião de Decisão Nova)\n\n`;
if ((estadoAnterior.total || 0) === 0) {
  bloco += `1ª execução — linha de base gravada (${linhas.length} decisões existentes hoje). Próximas execuções comparam a partir daqui.\n`;
} else if (novasLinhas.length === 0) {
  bloco += `Nenhuma decisão nova em decisoes.md desde a última checagem (${estadoAnterior.total} linhas antes, ${linhas.length} agora).\n`;
} else {
  bloco += `${novasLinhas.length} decisão(ões) nova(s) desde a última checagem — confirmar que quem produz conteúdo/copy/design já leu:\n\n`;
  for (const l of novasLinhas) {
    bloco += `- [${l.categoria}] ${l.data}: ${l.resumo}\n`;
  }
}

if (!fs.existsSync(ALERTAS)) {
  fs.writeFileSync(ALERTAS, '# Alertas automáticos — n8n\n\n' + bloco, 'utf8');
} else {
  fs.appendFileSync(ALERTAS, bloco, 'utf8');
}

return [{ json: { totalAntes: estadoAnterior.total || 0, totalAgora: linhas.length, novas: novasLinhas.length } }];
